import {EQUIPMENT,MATERIALS,ECONOMY,catalogItem} from './equipment-catalog.js';
import {experimentById,eligibility} from './experiment-definitions.js';
import {tutorialEvent} from './tutorial.js';
const idToken=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
export function purchase(player,id,quantity=1){const item=catalogItem(id);if(!item)return{ok:false,message:'Unknown catalogue item.'};if(!Number.isSafeInteger(quantity)||quantity<1||quantity>100)return{ok:false,message:'Choose a valid purchase quantity.'};if(!Number.isSafeInteger(item.price)||item.price<0)return{ok:false,message:'This item is available as a reward only.'};const cost=item.price*quantity;if(player.currency<cost)return{ok:false,message:'Not enough '+ECONOMY.name+'.'};const inventory=item.type==='equipment'?player.equipment:player.materials;if((inventory[id]||0)+quantity>99999)return{ok:false,message:'Inventory limit reached.'};player.currency-=cost;inventory[id]=(inventory[id]||0)+quantity;return{ok:true,message:`Obtained ${quantity} × ${item.name}.`,cost};}
export function applyReward(player,reward){if(!reward||typeof reward.id!=='string'||!reward.id||reward.id.length>150)return{ok:false,message:'A stable reward ID is required.'};if(player.claims.includes(reward.id))return{ok:false,message:'This reward has already been claimed.'};const credits=reward.credits||0;if(!Number.isSafeInteger(credits)||credits<0||player.currency+credits>1e9)return{ok:false,message:'Invalid reward credits.'};for(const [kind,catalog]of [['equipment',EQUIPMENT],['materials',MATERIALS]])for(const [id,n]of Object.entries(reward[kind]||{}))if(!catalog[id]||!Number.isSafeInteger(n)||n<1||(player[kind][id]||0)+n>99999)return{ok:false,message:'Invalid reward inventory.'};player.currency+=credits;for(const kind of ['equipment','materials'])for(const [id,n]of Object.entries(reward[kind]||{}))player[kind][id]=(player[kind][id]||0)+n;player.claims.push(reward.id);return{ok:true,message:'Reward applied.'};}
export const claimTrialGrant=player=>{const r=applyReward(player,{id:'testing-allowance-v1',credits:ECONOMY.trialGrant});return{...r,message:r.ok?'Testing allowance added. Prices and future mission rewards remain provisional.':r.message};};
// Explicit playtest shortcut; repeat clicks replenish rather than multiply stock.
export const TESTING_STOCK=100;
export function stockAllLabsForTesting(player){
 for(const [kind,catalog]of [['equipment',EQUIPMENT],['materials',MATERIALS]])for(const id of Object.keys(catalog))player[kind][id]=Math.max(TESTING_STOCK,player[kind][id]||0);
 return{ok:true,message:`Testing stock ready: at least ${TESTING_STOCK} of every equipment type and supply. All laboratories are available.`};
}
export function reserveAttempt(player,id){const e=experimentById(id);if(!e)throw Error('Unknown experiment.');const eligible=eligibility(player,id);if(!eligible.available)throw Error(eligible.reasons.join('; '));const supplies={...e.materials};for(const [id,n]of Object.entries(e.optionalMaterials||{}))supplies[id]=(supplies[id]||0)+Math.min(n,Math.max(0,(player.materials[id]||0)-(supplies[id]||0)));for(const [id,n]of Object.entries(supplies))player.materials[id]-=n;const attempt={id:idToken(),experiment:id,supplies,status:'active',startedAt:new Date().toISOString()};player.attempts[id]=attempt;tutorialEvent(player,'view-requirements');tutorialEvent(player,'start-experiment');return attempt;}
export async function launchExperiment(store,id){const {result}=await store.transact(p=>reserveAttempt(p,id));return result;}
export function completeAttempt(player,id,attemptId){const a=player.attempts[id];if(!a||a.id!==attemptId||a.status!=='active')return false;a.status='completed';a.completedAt=new Date().toISOString();if(!player.completed.includes(id))player.completed.push(id);return true;}
export function apparatusAccess(player,definition,attempt){const access={};for(const [id,part]of Object.entries(definition.apparatus)){access[id]=Boolean(part.provided||part.equipment&&(player.equipment[part.equipment]||0)>=part.ordinal||part.material&&(attempt.supplies[part.material]||0)>=part.ordinal);}return access;}
